import java.nio.file.Path;
import java.security.MessageDigest;

public class MistSpan {
    static final int ROW = 48;

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        if (wanted.length != 16) return new byte[0];
        byte[] pins = Files.exists(silo.resolve("pin.bin"))
                ? Files.readAllBytes(silo.resolve("pin.bin")) : new byte[0];
        byte[] blob = Files.exists(silo.resolve("blob.bin"))
                ? Files.readAllBytes(silo.resolve("blob.bin")) : new byte[0];
        for (int pos = 0; pos + ROW <= pins.length; pos += ROW) {
            ByteBuffer row = ByteBuffer.wrap(pins, pos, ROW);
            byte[] magic = new byte[4]; row.get(magic);
            long off = row.getLong();
            int len = row.getInt();
            int crc = row.getInt();
            byte[] id = new byte[16]; row.get(id);
            if (!same(id, wanted)) continue;
            if (!magic(magic)) return new byte[0];
            byte[] payload = body(blob, off, len);
            if (payload == null || Crc.of(payload) != crc || !same(id, idOf(payload)))
                return new byte[0];
            return payload;
        }
        return new byte[0];
    }

    static byte[] body(byte[] blob, long off, int len) {
        if (off < 0 || len < 0 || off > blob.length || off + 4L + len > blob.length)
            return null;
        int p = (int) off;
        int framed = ByteBuffer.wrap(blob, p, 4).getInt();
        if (framed != len) return null;
        byte[] out = new byte[len];
        System.arraycopy(blob, p + 4, out, 0, len);
        return out;
    }

    static byte[] idOf(byte[] payload) throws Exception {
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(payload);
        byte[] id = new byte[16];
        System.arraycopy(digest, 0, id, 0, 16);
        return id;
    }

    static boolean magic(byte[] x) {
        return x.length == 4 && x[0] == 'P' && x[1] == 'N' && x[2] == '0' && x[3] == '1';
    }

    static boolean same(byte[] x, byte[] y) {
        if (x.length != y.length) return false;
        int diff = 0;
        for (int i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
        return diff == 0;
    }
}
