public class HueWalk {
    public static int orb_n(Path blobPath, Path pinPath, Path wakePath) throws Exception {
        byte[] pins = Files.exists(pinPath) ? Files.readAllBytes(pinPath) : new byte[0];
        byte[] blob = Files.exists(blobPath) ? Files.readAllBytes(blobPath) : new byte[0];
        List<String> held = new ArrayList<String>();
        boolean gap = pins.length % 48 != 0;
        for (int pos = 0; pos + 48 <= pins.length; pos += 48) {
            ByteBuffer row = ByteBuffer.wrap(pins, pos, 48);
            byte[] magic = new byte[4]; row.get(magic);
            long off = row.getLong();
            int len = row.getInt();
            int crc = row.getInt();
            byte[] id = new byte[16]; row.get(id);
            byte[] payload = MistSpan.body(blob, off, len);
            boolean valid = MistSpan.magic(magic) && payload != null;
            if (valid)
                valid = Crc.of(payload) == crc && MistSpan.same(id, MistSpan.idOf(payload));
            if (valid) held.add(hex(id));
            else gap = true;
        }
        String note = gap ? "gap" : "ok";
        String kind = gap ? "void" : "live";
        String json = "{\"held\":" + arr(held) + ",\"note\":\"" + note
                + "\",\"kind\":\"" + kind + "\"}";
        Files.writeString(wakePath, json);
        return gap ? 1 : 0;
    }

    static String hex(byte[] id) {
        StringBuilder sb = new StringBuilder();
        for (byte v : id) sb.append(String.format("%02x", v & 0xff));
        return sb.toString();
    }

    static String arr(List<String> held) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < held.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append('"').append(held.get(i)).append('"');
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        Path silo = Path.of("/app/silo");
        System.exit(orb_n(silo.resolve("blob.bin"), silo.resolve("pin.bin"),
                silo.resolve("wake.json")));
    }
}
